    begin
        rst <= '1';
        wait for 3 * CLK_PERIOD;
        rst <= '0';
        wait for 52 * CLK_PERIOD;

        check_reg(regs, 10, x"00000001", "x10", errors);
        check_reg(regs, 11, x"00000001", "x11", errors);
        check_reg(regs, 29, x"00000000", "x29", errors);

        finish_test("tb_branch_with_forwarding", errors);
